/*
 * app.js — the wiki shell.
 *
 * Every page is built at request time from a Markdown or scene file in this
 * repository. content/index.json is generated by tools/build.mjs from the
 * front matter of those files; nothing here holds a copy of the writing.
 */

import { renderMarkdown, parseFrontMatter, escapeHtml } from './markdown.js';
import { renderScene } from './script.js';

const view = document.getElementById('view');
const mastheadTitle = document.getElementById('masthead-title');
const progress = document.getElementById('progress');
const drawer = document.getElementById('drawer');
const scrim = document.getElementById('scrim');

const files = new Map();
const REDUCED = matchMedia('(prefers-reduced-motion: reduce)');

let site = null;
let corpus = null;
let indexing = null;

/* ------------------------------------------------------------- plumbing -- */

async function read(path) {
  if (files.has(path)) return files.get(path);
  const response = await fetch(path, { cache: 'no-cache' });
  if (!response.ok) throw new Error(`Missing file: ${path}`);
  const text = await response.text();
  files.set(path, text);
  return text;
}

const section = (slug) => site.sections.find((s) => s.slug === slug);
const chapter = (id) => site.chapters.find((c) => c.id === id) || site.chapters[0];

const icon = (name, cls = 'icon') => `<svg class="${cls}" aria-hidden="true"><use href="#${name}"/></svg>`;

function plate(image, alt, extra = '') {
  const src = image && site.images[image];
  if (!src) return `<div class="plate empty ${extra}"></div>`;
  return `<div class="plate ${extra}"><img src="${escapeHtml(src)}" alt="${escapeHtml(alt)}" loading="lazy" decoding="async"></div>`;
}

const ornament = (violet = false) =>
  `<div class="orn ${violet ? 'violet' : ''}" aria-hidden="true"><i></i></div>`;

/* ----------------------------------------------------------------- dials */

const TAU = Math.PI / 180;
const SWEEP = 270;
const START = 135;

const point = (deg, r = 38) => [
  (50 + r * Math.cos(deg * TAU)).toFixed(2),
  (50 + r * Math.sin(deg * TAU)).toFixed(2),
];

function ticks() {
  const marks = [];
  for (let i = 0; i <= 20; i += 1) {
    const deg = START + (SWEEP * i) / 20;
    const major = i % 5 === 0;
    const [x1, y1] = point(deg, major ? 30 : 33);
    const [x2, y2] = point(deg, 36);
    marks.push(`<line class="dial-tick ${major ? 'major' : ''}" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"/>`);
  }
  return marks.join('');
}

/** One analogue gauge. The needle and the numeral are animated on reveal. */
function dial(stat, index) {
  const max = Math.max(stat.max || 1, 1);
  const fraction = Math.max(0, Math.min(1, stat.value / max));
  const [sx, sy] = point(START);

  const detail = stat.detail || [];

  return `
    <${detail.length ? 'button type="button" class="dial" aria-expanded="false"' : 'div class="dial"'}
         data-value="${stat.value}" data-fraction="${fraction}" data-index="${index}"
         data-prefix="${escapeHtml(stat.prefix || '')}" data-suffix="${escapeHtml(stat.suffix || '')}">
      <svg viewBox="0 0 100 100" role="img"
           aria-label="${escapeHtml(stat.label)}: ${stat.value}${escapeHtml(stat.suffix || '')}">
        <path class="dial-rim" d="M ${sx} ${sy} A 38 38 0 1 1 ${point(START + SWEEP)[0]} ${point(START + SWEEP)[1]}"/>
        <g class="dial-ticks">${ticks()}</g>
        <path class="dial-arc" d="M ${sx} ${sy}"/>
        <line class="dial-needle" x1="50" y1="50" x2="50" y2="16"/>
        <circle class="dial-hub" cx="50" cy="50" r="3.2"/>
      </svg>
      <b class="dial-value">0</b>
      <span class="dial-label">${escapeHtml(stat.label)}</span>
      ${detail.length ? '<span class="dial-more" aria-hidden="true"></span>' : ''}
    </${detail.length ? 'button' : 'div'}>`;
}

/** The list a dial opens: what the reading is actually made of. */
function breakdown(stat) {
  const rows = (stat.detail || []).map((row) => {
    const inner = `<b>${escapeHtml(row.label)}</b>${row.note ? `<small>${escapeHtml(row.note)}</small>` : ''}`;
    return `<li>${row.route ? `<a href="${row.route}">${inner}</a>` : `<span>${inner}</span>`}</li>`;
  }).join('');

  return `<div class="breakdown" hidden>
    <p class="breakdown-head">${escapeHtml(stat.label)}</p>
    ${rows ? `<ul>${rows}</ul>` : '<p class="note">Nothing recorded in the scripts.</p>'}
  </div>`;
}

function dials(stats) {
  if (!stats || !stats.length) return '';
  return `<div class="dial-set">
    <div class="dials">${stats.map(dial).join('')}</div>
    ${stats.map(breakdown).join('')}
  </div>`;
}

function runDial(node) {
  const target = Number(node.dataset.fraction);
  const value = Number(node.dataset.value);
  const prefix = node.dataset.prefix;
  const suffix = node.dataset.suffix;
  const arc = node.querySelector('.dial-arc');
  const needle = node.querySelector('.dial-needle');
  const readout = node.querySelector('.dial-value');

  // `t` drives the needle (a fraction of full scale); `p` drives the numeral
  // (a fraction of the value). Conflating the two makes the readout land on
  // value × fraction instead of value.
  const paint = (t, p) => {
    const deg = START + SWEEP * t;
    const [sx, sy] = point(START);
    const [ex, ey] = point(deg);
    arc.setAttribute('d', t < 0.001
      ? `M ${sx} ${sy}`
      : `M ${sx} ${sy} A 38 38 0 ${SWEEP * t > 180 ? 1 : 0} 1 ${ex} ${ey}`);
    // The needle is drawn point-to-point rather than rotated: SVG transform
    // origins vary between engines, endpoints do not.
    const [nx, ny] = point(deg, 29);
    needle.setAttribute('x2', nx);
    needle.setAttribute('y2', ny);
    readout.innerHTML = `${prefix ? `<small>${prefix}</small>` : ''}${Math.round(value * p)}`
      + `${suffix ? `<small>${suffix}</small>` : ''}`;
  };

  if (REDUCED.matches) { paint(target, 1); return; }

  const duration = 1100;
  const started = performance.now();
  const step = (now) => {
    const p = Math.min(1, (now - started) / duration);
    const eased = 1 - Math.pow(1 - p, 3);            // settles like a real needle
    paint(target * eased, eased);
    if (p < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

/* ---------------------------------------------------------------- chrome -- */

function setChrome(label, href = '#/', accent) {
  mastheadTitle.textContent = label || '';
  mastheadTitle.href = href;
  mastheadTitle.hidden = !label;
  document.title = label ? `${label} · Below the Bloom` : 'Below the Bloom — The Official Wiki';
  view.style.setProperty('--accent', accent || 'var(--cyan)');
}

let watcher = null;
function watchReveals() {
  if (!('IntersectionObserver' in window)) {
    view.querySelectorAll('.fade, .gateways, .dial').forEach((n) => {
      n.classList.add('seen');
      if (n.classList.contains('dial')) runDial(n);
    });
    return;
  }
  if (watcher) watcher.disconnect();

  watcher = new IntersectionObserver((rows) => {
    for (const row of rows) {
      if (!row.isIntersecting) continue;
      row.target.classList.add('seen');
      if (row.target.classList.contains('dials')) {
        row.target.querySelectorAll('.dial').forEach(runDial);
      }
      watcher.unobserve(row.target);
    }
  }, { rootMargin: '0px 0px -6% 0px', threshold: 0.05 });

  view.querySelectorAll('.fade, .gateways, .dials').forEach((n) => watcher.observe(n));
}

function paint(html) {
  view.innerHTML = html;
  window.scrollTo(0, 0);
  view.classList.remove('enter');
  void view.offsetWidth;
  view.classList.add('enter');
  watchReveals();
  wireDials();
  trackScroll();
}

/** Clicking a dial opens what the reading is made of, and closes any other. */
function wireDials() {
  for (const set of view.querySelectorAll('.dial-set')) {
    const panels = [...set.querySelectorAll('.breakdown')];
    for (const button of set.querySelectorAll('button.dial')) {
      button.addEventListener('click', () => {
        const panel = panels[Number(button.dataset.index)];
        const open = button.getAttribute('aria-expanded') === 'true';

        for (const other of set.querySelectorAll('button.dial')) other.setAttribute('aria-expanded', 'false');
        for (const other of panels) other.hidden = true;

        if (!open) {
          button.setAttribute('aria-expanded', 'true');
          panel.hidden = false;
        }
      });
    }
  }
}

function trackScroll() {
  const span = document.documentElement.scrollHeight - window.innerHeight;
  const ratio = span > 24 ? Math.min(1, window.scrollY / span) : 0;
  progress.style.transform = `scaleX(${ratio})`;
  document.body.classList.toggle('scrolled', window.scrollY > 40);
  // The page sinks as you read: the ambient wash deepens with scroll depth.
  document.documentElement.style.setProperty('--sink', ratio.toFixed(3));
  portalScroll();
}

const waiting = (label = 'Sounding the depth') =>
  paint(`<div class="waiting"><i></i><p>${escapeHtml(label)}</p></div>`);

function lost(error) {
  setChrome('Below the Bloom');
  paint(`
    <div class="shell">
      <header class="head">
        <p class="kicker">Signal lost</p>
        <h1 class="title">Nothing here</h1>
        ${ornament()}
        <p class="standfirst">${escapeHtml(error.message || String(error))}</p>
      </header>
      <div class="ledger">
        <a class="ledger-row" href="#/"><span><b class="ledger-name">Return to the surface</b></span>${icon('i-chevron-right', 'icon chev')}</a>
      </div>
    </div>`);
}

/* ---------------------------------------------------------------- drawer -- */

function buildDrawer() {
  document.getElementById('drawer-links').innerHTML = `
    <a href="#/" data-route="#/">${icon('i-home')}<span>Home</span></a>
    ${site.sections.map((s) => `
      <a href="#/${s.slug}" data-route="#/${s.slug}" style="--gw:${s.accent}">
        ${icon(s.icon)}<span>${escapeHtml(s.title)}</span>
      </a>`).join('')}
    <a href="#/search" data-route="#/search">${icon('i-search')}<span>Search</span></a>`;
}

function toggleDrawer(open) {
  const button = document.getElementById('menu-open');
  drawer.hidden = false;
  scrim.hidden = false;
  requestAnimationFrame(() => {
    drawer.classList.toggle('open', open);
    scrim.classList.toggle('open', open);
  });
  document.body.classList.toggle('locked', open);
  button.setAttribute('aria-expanded', String(open));
  if (open) drawer.querySelector('a')?.focus();
  else setTimeout(() => {
    if (!drawer.classList.contains('open')) { drawer.hidden = true; scrim.hidden = true; }
  }, 440);
}

function markDrawer() {
  const base = `#/${location.hash.replace(/^#\/?/, '').split('/')[0].split('?')[0]}`;
  drawer.querySelectorAll('[data-route]').forEach((link) =>
    link.classList.toggle('current', link.dataset.route === base));
}

/* ----------------------------------------------------------------- views -- */

/* ---------------------------------------------------------------- portal */
/*
 * The landing page: three stations, three framed views of the same painting,
 * all in normal document flow so everything scrolls together, locked. The
 * hero shows the top of the art with the wordmark; the gateways sit on its
 * trench band; the cave at the bottom of the art closes the page. All
 * cropping is plain CSS — nothing here computes layout.
 */

const ROMAN = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII'];

function home() {
  setChrome('');
  document.body.classList.remove('scrolled');

  const gates = site.sections.map((s, i) => `
    <a class="gate" href="#/${s.slug}" style="--gw:${s.accent};--gi:${i}">
      <span class="gate-glare" aria-hidden="true"></span>
      <span class="gate-emblem">${icon(s.icon)}</span>
      <span class="gate-text">
        <b>${escapeHtml(s.title)}</b>
        <small>${escapeHtml(s.standfirst)}</small>
      </span>
      <span class="gate-index">${ROMAN[i] || ''}</span>
      ${icon('i-chevron-right', 'icon gate-chev')}
    </a>`).join('');

  const art = escapeHtml(site.site.art);

  paint(`
    <div class="portal" id="portal" style="--art:url('${art}')">
      <section class="st st-hero">
        <div class="st-art" aria-hidden="true">
          <img src="${art}" alt="" fetchpriority="high">
          <span class="portal-pulse"></span>
        </div>
        <canvas id="portal-fx" aria-hidden="true"></canvas>
        <div class="portal-rays" aria-hidden="true"><i></i><i></i><i></i></div>
        <div class="st-hero-copy shell">
          <p class="banner">${escapeHtml(site.site.banner)}</p>
          <p class="creed">${site.site.creed.map(escapeHtml).join('<br>')}</p>
          <a class="cta" href="#/story/chapter-1/scene-01">
            <span class="cta-glare" aria-hidden="true"></span>
            <b>Begin the Descent</b>
            <small>Chapter One · The Crash</small>
          </a>
          <div class="scroll-cue" aria-hidden="true">
            <span>Descend</span>
            ${icon('i-chevron-down', '')}
          </div>
        </div>
      </section>

      <section class="st st-gates">
        <div class="st-art" aria-hidden="true"><img src="${art}" alt="" loading="lazy"></div>
        <div class="shell st-gates-body">
          <p class="banner">Enter the Archive</p>
          <nav class="gateways" aria-label="Wiki sections">${gates}</nav>
        </div>
      </section>

      <section class="st st-still">
        <p class="epitaph">${escapeHtml(site.site.epitaph)}</p>
      </section>

      <section class="st st-cave" aria-label="Two survivors in a cave, far below">
        <div class="st-art" aria-hidden="true">
          <img src="${art}" alt="" loading="lazy">
          <span class="portal-lantern"></span>
        </div>
      </section>

      <div class="depth-rail" aria-hidden="true">
        <span class="depth-track"><i class="depth-node"></i></span>
        <b id="depth-read">0000m</b>
      </div>
    </div>`);

  portalFX();
}

/*
 * Life in the water of the first screen: plankton twinkling, bubbles rising,
 * and embers off the scavenger's ribs. Coordinates hang off the art's stage
 * width so the embers stay on the bird at every size.
 */
function portalFX() {
  const canvas = document.getElementById('portal-fx');
  if (!canvas || REDUCED.matches) return;

  const context = canvas.getContext('2d');
  let frame = null;
  let W = 0;
  let H = 0;
  let plankton = [];
  let bubbles = [];
  let embers = [];

  const rand = (a, b) => a + Math.random() * (b - a);

  const seed = () => {
    if (!canvas.isConnected) return;
    const ratio = Math.min(devicePixelRatio || 1, 1.5);
    W = canvas.offsetWidth;
    H = canvas.offsetHeight;
    canvas.width = W * ratio;
    canvas.height = H * ratio;
    context.setTransform(ratio, 0, 0, ratio, 0, 0);

    const stage = document.querySelector('.st-hero .st-art img')?.offsetWidth || W;
    const left = (W - stage) / 2;

    plankton = Array.from({ length: 42 }, () => ({
      x: rand(0.04, 0.96) * W,
      y: rand(0.08, 0.96) * H,
      r: rand(0.4, 1.2),
      phase: rand(0, Math.PI * 2),
      speed: rand(0.4, 1.1),
      warm: Math.random() > 0.82,
    }));

    bubbles = Array.from({ length: 12 }, () => ({
      x: rand(0.2, 0.8) * W,
      y: rand(0.5, 1) * H,
      r: rand(0.5, 1.7),
      up: rand(0.08, 0.26),
      sway: rand(0.4, 1.2),
      phase: rand(0, Math.PI * 2),
    }));

    // The scavenger's chest sits at (0.29, 0.285×ratio) of the art.
    embers = Array.from({ length: 7 }, () => ({
      hx: left + 0.29 * stage,
      hy: 0.616 * stage,
      x: 0, y: 0, vx: 0, vy: 0, life: 0, r: rand(0.4, 1.1),
    })).map((e) => ({ ...e, life: rand(0.1, 1), x: e.hx + rand(-14, 14), y: e.hy + rand(-14, 14), vx: rand(-0.04, 0.08), vy: rand(-0.1, -0.02) }));
  };

  const tick = (now) => {
    if (!canvas.isConnected) { frame = null; return; }
    context.clearRect(0, 0, W, H);

    for (const m of plankton) {
      const a = 0.08 + 0.2 * (0.5 + Math.sin(now / 1400 * m.speed + m.phase) / 2);
      context.beginPath();
      context.fillStyle = m.warm ? `rgba(190,140,255,${a})` : `rgba(140,225,240,${a})`;
      context.arc(m.x, m.y, m.r, 0, Math.PI * 2);
      context.fill();
    }

    for (const b of bubbles) {
      b.y -= b.up;
      if (b.y < 0.06 * H) { b.y = rand(0.75, 1) * H; b.x = rand(0.2, 0.8) * W; }
      const x = b.x + Math.sin(now / 1800 + b.phase) * b.sway * 6;
      const fade = Math.min(1, Math.max(0, (b.y / H - 0.05) * 4));
      context.beginPath();
      context.strokeStyle = `rgba(170,225,240,${0.15 * fade})`;
      context.lineWidth = 0.8;
      context.arc(x, b.y, b.r, 0, Math.PI * 2);
      context.stroke();
    }

    for (const e of embers) {
      e.x += e.vx;
      e.y += e.vy;
      e.life -= 0.004;
      if (e.life <= 0) {
        e.life = rand(0.4, 1);
        e.x = e.hx + rand(-14, 14);
        e.y = e.hy + rand(-14, 14);
        e.vx = rand(-0.04, 0.08);
        e.vy = rand(-0.1, -0.02);
      }
      context.beginPath();
      context.fillStyle = `rgba(235,160,70,${0.5 * Math.min(1, e.life * 2.4)})`;
      context.arc(e.x, e.y, e.r * e.life + 0.2, 0, Math.PI * 2);
      context.fill();
    }

    frame = requestAnimationFrame(tick);
  };

  const play = () => { if (!frame && canvas.isConnected) frame = requestAnimationFrame(tick); };
  const pause = () => { if (frame) { cancelAnimationFrame(frame); frame = null; } };

  document.addEventListener('visibilitychange', () => (document.hidden ? pause() : play()));
  addEventListener('resize', seed, { passive: true });
  seed();
  play();
}

/** The only scroll work the portal owns now: the depth readout. */
function portalScroll() {
  const read = document.getElementById('depth-read');
  if (!read) return;
  const span = document.documentElement.scrollHeight - innerHeight;
  const sink = span > 24 ? Math.min(1, scrollY / span) : 0;
  read.textContent = `${String(Math.round(sink * 3840)).padStart(4, '0')}m`;
}

const rosterIndex = (s) => `<div class="roster">${s.entries.map((item, i) => `
  <a class="entry fade" style="--i:${Math.min(i, 10)}" href="#/${s.slug}/${item.slug}">
    ${plate(item.image, item.name)}
    <p class="entry-name">${escapeHtml(item.name)}</p>
    <p class="entry-role">${escapeHtml(item.role)}</p>
  </a>`).join('')}</div>`;

const ledgerIndex = (s) => `<div class="ledger">${s.entries.map((item, i) => `
  <a class="ledger-row fade" style="--i:${Math.min(i, 10)}" href="#/${s.slug}/${item.slug}">
    <span>
      <b class="ledger-name">${escapeHtml(item.name)}</b>
      <small class="ledger-note">${escapeHtml(item.role)}</small>
    </span>
    ${icon('i-chevron-right', 'icon chev')}
  </a>`).join('')}</div>`;

function galleryIndex() {
  const plates = site.sections
    .filter((s) => s.entries)
    .flatMap((s) => s.entries.filter((e) => e.image && site.images[e.image])
      .map((e) => ({ ...e, section: s.slug, accent: s.accent })));

  if (!plates.length) {
    return `<p class="note" style="margin-top:30px">
      No plates yet. Drop images into <code>assets/img/</code>, run
      <code>node tools/build.mjs</code>, and every one of them appears here.
    </p>`;
  }

  return `<div class="gallery">${plates.map((item, i) => `
    <a class="fade" style="--i:${Math.min(i, 12)};--accent:${item.accent}" href="#/${item.section}/${item.slug}">
      <figure>${plate(item.image, item.name)}<figcaption>${escapeHtml(item.name)}</figcaption></figure>
    </a>`).join('')}</div>`;
}

function storyIndex() {
  const rows = site.chapters.map((book, i) => `
    <a class="ledger-row fade" style="--i:${Math.min(i, 10)}" href="#/story/${book.id}">
      <span>
        <b class="ledger-name">${escapeHtml(book.title)}</b>
        <small class="ledger-note">${escapeHtml(book.subtitle || '')}${book.subtitle ? ' — ' : ''}${book.acts.length} acts, ${book.scenes.length} scenes</small>
      </span>
      ${icon('i-chevron-right', 'icon chev')}
    </a>`).join('');

  return `<div class="ledger" style="margin-top:26px">${rows}</div>`;
}

function chapterIndex(book) {
  const acts = book.acts.map((act) => {
    const scenes = book.scenes.filter((s) => s.act === act.id);
    const rows = scenes.map((scene, i) => `
      <a class="ledger-row fade" style="--i:${Math.min(i, 8)}" href="#/story/${book.id}/${scene.slug}">
        <span>
          <b class="ledger-name"><span class="ledger-index">${String(scene.n).padStart(2, '0')}</span> &nbsp;${escapeHtml(scene.title)}</b>
          <small class="ledger-note">${escapeHtml(scene.synopsis)}</small>
        </span>
        ${icon('i-chevron-right', 'icon chev')}
      </a>`).join('');
    return `<h2 class="act">${escapeHtml(act.title)}<small>${escapeHtml(act.note)}</small></h2><div class="ledger">${rows}</div>`;
  }).join('');

  return `
    <div class="ledger" style="margin-top:26px">
      <a class="ledger-row fade" href="#/lore/${book.timeline || 'timeline'}">
        <span>
          <b class="ledger-name">${escapeHtml(book.title)} — Timeline</b>
          <small class="ledger-note">The whole run in order, beat by beat.</small>
        </span>
        ${icon('i-chevron-right', 'icon chev')}
      </a>
    </div>${acts}`;
}

function chapterView(chapterId) {
  const book = site.chapters.find((c) => c.id === chapterId);
  if (!book) throw new Error(`There is no chapter called “${chapterId}” in this wiki.`);

  const story = section('story');
  setChrome(book.title, '#/story', story.accent);

  paint(`
    <div class="shell">
      <header class="head">
        <p class="kicker">${escapeHtml(story.title)}</p>
        <h1 class="title">${escapeHtml(book.title)}</h1>
        ${ornament()}
        ${book.subtitle ? `<p class="standfirst">${escapeHtml(book.subtitle)}</p>` : ''}
      </header>
      ${chapterIndex(book)}
    </div>`);
}

function sectionView(slug) {
  const entry = section(slug);
  if (!entry) throw new Error(`There is no “${slug}” section in this wiki.`);
  setChrome(entry.title, `#/${slug}`, entry.accent);

  const body = entry.layout === 'roster' ? rosterIndex(entry)
    : entry.layout === 'ledger' ? ledgerIndex(entry)
    : entry.layout === 'story' ? storyIndex()
    : galleryIndex();

  const wide = entry.layout === 'roster' || entry.layout === 'gallery';

  paint(`
    <div class="shell${wide ? '-wide' : ''}">
      <header class="head">
        <p class="kicker">Below the Bloom</p>
        <h1 class="title">${escapeHtml(entry.title)}</h1>
        ${ornament()}
        <p class="standfirst">${escapeHtml(entry.standfirst)}</p>
      </header>
      ${body}
    </div>`);
}

function backlinks(rows) {
  if (!rows || !rows.length) return '';
  return `
    <aside class="backlinks">
      <h2>Referenced by</h2>
      <ul>${rows.map((r) => `
        <li><a href="${r.route}"><em>${escapeHtml(r.kind)}</em><span>${escapeHtml(r.name)}</span></a></li>`).join('')}
      </ul>
    </aside>`;
}

function pager(previous, next) {
  if (!previous && !next) return '';
  return `
    <nav class="pager">
      ${previous ? `<a href="${previous.href}">${icon('i-arrow-left')}<span><b>${escapeHtml(previous.label)}</b><i>${escapeHtml(previous.name)}</i></span></a>` : '<span></span>'}
      ${next ? `<a class="next" href="${next.href}"><span><b>${escapeHtml(next.label)}</b><i>${escapeHtml(next.name)}</i></span>${icon('i-arrow-right')}</a>` : '<span></span>'}
    </nav>`;
}

let neighbours = { previous: null, next: null };

async function entryView(sectionSlug, entrySlug) {
  const parent = section(sectionSlug);
  if (!parent || !parent.entries) throw new Error(`There is no “${sectionSlug}” section in this wiki.`);

  const item = parent.entries.find((e) => e.slug === entrySlug);
  if (!item) throw new Error(`“${entrySlug}” is not in ${parent.title}.`);

  setChrome(item.name, `#/${sectionSlug}`, parent.accent);
  waiting();

  const { body } = parseFrontMatter(await read(item.file));
  const { html } = renderMarkdown(body.replace(/^\s*#\s+.+$/m, ''), site.images);

  const position = parent.entries.indexOf(item);
  const previous = parent.entries[position - 1];
  const next = parent.entries[position + 1];
  neighbours = {
    previous: previous && `#/${sectionSlug}/${previous.slug}`,
    next: next && `#/${sectionSlug}/${next.slug}`,
  };

  const art = item.image && site.images[item.image];
  const tags = (item.tags || []).map((t) => `<span>${escapeHtml(t)}</span>`).join('');

  paint(`
    <article>
      ${art ? `<div class="dossier-art"><img src="${escapeHtml(art)}" alt="${escapeHtml(item.name)}" fetchpriority="high"></div>` : ''}
      <div class="shell">
        <header class="dossier-head ${art ? '' : 'bare'}">
          <p class="kicker">${escapeHtml(parent.title)}</p>
          <h1 class="title">${escapeHtml(item.name)}</h1>
          <p class="title-sub">${escapeHtml(item.role)}</p>
          ${tags ? `<div class="tagset">${tags}</div>` : ''}
          ${ornament()}
        </header>
        ${dials(item.stats)}
        <div class="prose fade">${html}</div>
        ${backlinks(item.backlinks)}
        ${pager(
          previous && { href: neighbours.previous, label: 'Previous', name: previous.name },
          next && { href: neighbours.next, label: 'Next', name: next.name },
        )}
      </div>
    </article>`);
}

async function sceneView(chapterId, slug) {
  const book = chapter(chapterId);
  const position = book.scenes.findIndex((s) => s.slug === slug);
  const scene = book.scenes[position];
  if (!scene) throw new Error(`${book.title} has no scene called “${slug}”.`);

  const story = section('story');
  setChrome(`Scene ${String(scene.n).padStart(2, '0')}`, `#/story/${book.id}`, story.accent);
  waiting('Surfacing the scene');

  const { body } = parseFrontMatter(await read(scene.file));
  const { html, cast } = renderScene(body, site.images);

  const act = book.acts.find((a) => a.id === scene.act);
  const previous = book.scenes[position - 1];
  const next = book.scenes[position + 1];
  neighbours = {
    previous: previous && `#/story/${book.id}/${previous.slug}`,
    next: next && `#/story/${book.id}/${next.slug}`,
  };

  paint(`
    <article class="shell">
      <header class="head" style="text-align:left">
        <p class="kicker">${escapeHtml(act ? act.title : book.title)}</p>
        <h1 class="title">${escapeHtml(scene.title)}</h1>
        <p class="scene-meta">${escapeHtml(scene.location)}</p>
        <p class="standfirst" style="text-align:left;margin-inline:0">${escapeHtml(scene.synopsis)}</p>
        ${cast.length ? `<div class="tagset">${cast.map((n) => `<span>${escapeHtml(n)}</span>`).join('')}</div>` : ''}
      </header>
      ${dials(scene.stats)}
      <div class="screenplay fade">${html}</div>
      ${backlinks(scene.backlinks)}
      ${pager(
        previous && { href: neighbours.previous, label: `Scene ${previous.n}`, name: previous.title },
        next ? { href: neighbours.next, label: `Scene ${next.n}`, name: next.title }
             : { href: `#/lore/${book.timeline || 'timeline'}`, label: 'End of chapter', name: 'The timeline' },
      )}
    </article>`);
}

/* ---------------------------------------------------------------- search -- */

async function buildCorpus(onTick) {
  if (corpus) return corpus;
  if (indexing) return indexing;

  const documents = [];
  for (const s of site.sections) {
    for (const item of s.entries || []) {
      documents.push({ kind: s.title, route: `#/${s.slug}/${item.slug}`, name: item.name, note: item.role, file: item.file });
    }
  }
  for (const book of site.chapters) {
    for (const scene of book.scenes) {
      documents.push({
        kind: 'Scene',
        route: `#/story/${book.id}/${scene.slug}`,
        name: `${String(scene.n).padStart(2, '0')} · ${scene.title}`,
        note: scene.synopsis,
        file: scene.file,
      });
    }
  }

  indexing = (async () => {
    let done = 0;
    const queue = [...documents];
    const worker = async () => {
      while (queue.length) {
        const doc = queue.shift();
        try { doc.text = parseFrontMatter(await read(doc.file)).body; } catch { doc.text = ''; }
        done += 1;
        onTick?.(done, documents.length);
      }
    };
    await Promise.all(Array.from({ length: 5 }, worker));
    corpus = documents;
    indexing = null;
    return documents;
  })();

  return indexing;
}

function excerpt(text, term) {
  const at = text.toLowerCase().indexOf(term);
  if (at < 0) return '';
  const from = Math.max(0, at - 55);
  const slice = text.slice(from, at + term.length + 95).replace(/\s+/g, ' ').trim();
  const safe = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return `${from ? '…' : ''}${escapeHtml(slice).replace(new RegExp(safe, 'ig'), (h) => `<mark>${h}</mark>`)}…`;
}

function searchView(query) {
  setChrome('Search', '#/search');

  paint(`
    <div class="shell">
      <header class="head">
        <p class="kicker">Below the Bloom</p>
        <h1 class="title">Search</h1>
        ${ornament()}
        <p class="standfirst">Every article and all forty-eight scenes, in full.</p>
      </header>
      <div class="search-shell">
        <div class="search-field">
          ${icon('i-search')}
          <input id="q" type="search" inputmode="search" autocomplete="off" spellcheck="false"
                 placeholder="Froststalker, the crown, prosthetic…" value="${escapeHtml(query)}"
                 aria-label="Search the wiki">
        </div>
        <div id="hits" class="hits"><p class="note" style="padding-top:18px">Type at least two letters.</p></div>
      </div>
    </div>`);

  const input = document.getElementById('q');
  const hits = document.getElementById('hits');
  let timer;

  const run = async (raw) => {
    const term = raw.trim().toLowerCase();
    if (term.length < 2) {
      hits.innerHTML = '<p class="note" style="padding-top:18px">Type at least two letters.</p>';
      return;
    }

    hits.innerHTML = '<p class="note" style="padding-top:18px">Reading the archive…</p>';
    const documents = await buildCorpus((done, total) => {
      if (!corpus) hits.innerHTML = `<p class="note" style="padding-top:18px">Reading the archive… ${done}/${total}</p>`;
    });

    const found = [];
    for (const doc of documents) {
      const meta = `${doc.name} ${doc.note}`.toLowerCase();
      const body = doc.text || '';
      const inMeta = meta.includes(term);
      const count = body.toLowerCase().split(term).length - 1;
      if (!inMeta && !count) continue;
      found.push({ doc, score: (inMeta ? 500 : 0) + count, snippet: count ? excerpt(body, term) : escapeHtml(doc.note) });
    }
    found.sort((a, b) => b.score - a.score);

    if (!found.length) {
      hits.innerHTML = `<p class="note" style="padding-top:18px">The archive holds nothing for “${escapeHtml(raw)}”.</p>`;
      return;
    }

    hits.innerHTML = found.slice(0, 40).map((hit) => `
      <a class="hit" href="${hit.doc.route}">
        <span class="hit-kind">${escapeHtml(hit.doc.kind)}</span>
        <b class="hit-name">${escapeHtml(hit.doc.name)}</b>
        <span class="hit-snip">${hit.snippet}</span>
      </a>`).join('');
  };

  input.addEventListener('input', () => {
    clearTimeout(timer);
    const value = input.value;
    timer = setTimeout(() => {
      history.replaceState(null, '', value.trim() ? `#/search?q=${encodeURIComponent(value.trim())}` : '#/search');
      run(value);
    }, 200);
  });

  if (query) run(query);
  if (matchMedia('(min-width: 1000px)').matches) input.focus();
}

/* ---------------------------------------------------------------- router -- */

async function route() {
  const raw = location.hash.replace(/^#\/?/, '');
  const [path, search] = raw.split('?');
  const parts = path.split('/').filter(Boolean);
  const params = new URLSearchParams(search || '');
  const known = new Set(site.sections.map((s) => s.slug));

  if (drawer.classList.contains('open')) toggleDrawer(false);
  neighbours = { previous: null, next: null };

  try {
    if (!parts.length) home();
    else if (parts[0] === 'search') searchView(params.get('q') || '');
    else if (parts[0] === 'story' && parts.length >= 3) await sceneView(parts[1], parts[2]);
    else if (parts[0] === 'story' && parts.length === 2) chapterView(parts[1]);
    else if (known.has(parts[0]) && parts.length >= 2) await entryView(parts[0], parts[1]);
    else if (known.has(parts[0])) sectionView(parts[0]);
    else throw new Error('That page is not part of this archive.');
  } catch (error) {
    lost(error);
  }

  markDrawer();
}

/* -------------------------------------------------------------- ambience -- */

function drift() {
  const canvas = document.getElementById('drift');
  if (!canvas || REDUCED.matches) return;

  const context = canvas.getContext('2d');
  let motes = [];
  let frame = null;

  const size = () => {
    const ratio = Math.min(devicePixelRatio || 1, 2);
    canvas.width = innerWidth * ratio;
    canvas.height = innerHeight * ratio;
    context.setTransform(ratio, 0, 0, ratio, 0, 0);

    motes = Array.from({ length: innerWidth < 640 ? 26 : 46 }, () => ({
      x: Math.random() * innerWidth,
      y: Math.random() * innerHeight,
      r: Math.random() * 1.6 + 0.25,
      up: Math.random() * 0.24 + 0.03,
      phase: Math.random() * Math.PI * 2,
      swing: Math.random() * 0.5 + 0.15,
      warm: Math.random() > 0.72,
      a: Math.random() * 0.32 + 0.06,
    }));
  };

  const tick = (now) => {
    context.clearRect(0, 0, innerWidth, innerHeight);
    for (const m of motes) {
      m.y -= m.up;
      const x = m.x + Math.sin(now / 2600 + m.phase) * m.swing * 18;
      if (m.y < -8) { m.y = innerHeight + 8; m.x = Math.random() * innerWidth; }
      context.beginPath();
      context.fillStyle = m.warm ? `rgba(165,108,255,${m.a})` : `rgba(140,220,235,${m.a})`;
      context.arc(x, m.y, m.r, 0, Math.PI * 2);
      context.fill();
    }
    frame = requestAnimationFrame(tick);
  };

  const play = () => { if (!frame) frame = requestAnimationFrame(tick); };
  const pause = () => { if (frame) { cancelAnimationFrame(frame); frame = null; } };

  addEventListener('resize', size, { passive: true });
  document.addEventListener('visibilitychange', () => (document.hidden ? pause() : play()));
  size();
  play();
}

/* ---------------------------------------------------------------- splash -- */

function splash(ready) {
  const node = document.getElementById('splash');
  const bar = document.getElementById('splash-bar');
  const depth = document.getElementById('splash-depth');
  const status = document.getElementById('splash-status');
  const skip = document.getElementById('splash-skip');

  document.body.classList.add('booting');

  const beats = ['Equalising pressure', 'Venting ballast', 'Running lights', 'Signal acquired'];
  const span = REDUCED.matches ? 400 : 2400;
  const started = performance.now();
  let done = false;

  const finish = () => {
    if (done) return;
    done = true;
    node.classList.add('done');
    document.body.classList.remove('booting');
    setTimeout(() => node.remove(), 900);
  };

  skip.addEventListener('click', finish);
  node.addEventListener('click', (e) => { if (e.target === node) finish(); });

  const step = (now) => {
    const p = Math.min(1, (now - started) / span);
    bar.style.width = `${(p * 100).toFixed(1)}%`;
    depth.textContent = String(Math.round(p * 3840)).padStart(4, '0');
    status.textContent = beats[Math.min(beats.length - 1, Math.floor(p * beats.length))];
    if (p < 1) requestAnimationFrame(step);
    else ready.then(finish);
  };
  requestAnimationFrame(step);

  // Never trap anyone behind it.
  setTimeout(finish, 7000);
}

/* ------------------------------------------------------------- bootstrap -- */

async function start() {
  addEventListener('scroll', trackScroll, { passive: true });
  addEventListener('hashchange', route);

  document.getElementById('menu-open').addEventListener('click', () => toggleDrawer(true));
  document.getElementById('menu-close').addEventListener('click', () => toggleDrawer(false));
  scrim.addEventListener('click', () => toggleDrawer(false));

  addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && drawer.classList.contains('open')) return toggleDrawer(false);
    if (event.target.matches('input, textarea')) return;
    if (event.key === 'ArrowLeft' && neighbours.previous) location.hash = neighbours.previous;
    if (event.key === 'ArrowRight' && neighbours.next) location.hash = neighbours.next;
  });

  // An image that never arrives leaves the sigil, not a broken frame.
  document.addEventListener('error', (event) => {
    const image = event.target;
    if (image.tagName !== 'IMG') return;
    const frame = image.closest('.plate, .dossier-art, .portal-art');
    if (frame) { frame.classList.add('empty', 'plate'); image.remove(); }
  }, true);

  drift();

  const loading = fetch('content/index.json', { cache: 'no-cache' })
    .then((response) => {
      if (!response.ok) throw new Error('The archive index could not be read.');
      return response.json();
    })
    .then((data) => {
      site = data;
      buildDrawer();
      route();
    })
    .catch(lost);

  splash(loading);
}

start();
